use super::*;
#[cfg(test)]
mod tests {
 use super::*;
 fn fixture()->(std::path::PathBuf,Connection){let root=std::env::temp_dir().join(format!("nestcraft-cr085-skills-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&root).unwrap();let c=Connection::open_in_memory().unwrap();c.execute_batch("CREATE TABLE capability(id TEXT PRIMARY KEY,kind TEXT,name TEXT,description TEXT,sourceRef TEXT,risk TEXT,enabled INTEGER,builtin INTEGER,createdAt INTEGER);CREATE UNIQUE INDEX cap_name ON capability(kind,name);CREATE TABLE setting_default(scope TEXT,key TEXT,value TEXT,updatedAt INTEGER,PRIMARY KEY(scope,key));").unwrap();(root,c)}
 fn edit<'a>(name:&'a str,old:Option<&'a str>,content:&'a str)->Edit<'a>{Edit{name,original:old,display:"技能显示名",description:"描述",content}}
 #[test] fn cr085_skill_rename_preserves_resources_and_enabled(){let(root,c)=fixture();save(&root,&c,edit("old",None,"old bytes")).unwrap();std::fs::create_dir(root.join("old/assets")).unwrap();std::fs::write(root.join("old/assets/test.bin"),b"attached").unwrap();c.execute("UPDATE capability SET enabled=0 WHERE name='old'",[]).unwrap();let id:String=c.query_row("SELECT id FROM capability WHERE name='old'",[],|r|r.get(0)).unwrap();save(&root,&c,edit("new",Some("old"),"# Full replacement\n")).unwrap();assert!(!root.join("old").exists());assert_eq!(std::fs::read(root.join("new/assets/test.bin")).unwrap(),b"attached");assert_eq!(std::fs::read_to_string(root.join("new/SKILL.md")).unwrap(),"# Full replacement\n");assert_eq!(c.query_row("SELECT id,enabled FROM capability WHERE name='new'",[],|r|Ok((r.get::<_,String>(0)?,r.get::<_,i64>(1)?))).unwrap(),(id,0));std::fs::remove_dir_all(root).unwrap();}
 #[test] fn cr085_skill_duplicate_and_missing_update_rejected(){let(root,c)=fixture();save(&root,&c,edit("one",None,"one")).unwrap();assert!(save(&root,&c,edit("one",None,"overwrite")).is_err());assert!(save(&root,&c,edit("two",Some("missing"),"bad")).is_err());assert_eq!(std::fs::read_to_string(root.join("one/SKILL.md")).unwrap(),"one");assert!(!root.join("two").exists());std::fs::remove_dir_all(root).unwrap();}
 #[test] fn cr085_skill_db_failure_restores_file_and_directory(){let(root,c)=fixture();save(&root,&c,edit("old",None,"original")).unwrap();c.execute_batch("CREATE TRIGGER fail_skill BEFORE UPDATE ON capability BEGIN SELECT RAISE(ABORT,'injected'); END;").unwrap();assert!(save(&root,&c,edit("new",Some("old"),"changed")).is_err());assert!(!root.join("new").exists());assert_eq!(std::fs::read_to_string(root.join("old/SKILL.md")).unwrap(),"original");assert_eq!(c.query_row("SELECT name FROM capability",[],|r|r.get::<_,String>(0)).unwrap(),"old");std::fs::remove_dir_all(root).unwrap();}
 #[test] fn cr085_skill_recovery_undoes_uncommitted_and_keeps_committed(){let(root,c)=fixture();save(&root,&c,edit("old",None,"original")).unwrap();std::fs::rename(root.join("old"),root.join("new")).unwrap();std::fs::write(root.join("new/SKILL.md"),"partial").unwrap();let work=root.join(".edit-interrupted");std::fs::create_dir(&work).unwrap();let journal=Journal{id:"interrupted".into(),old:Some("old".into()),new:"new".into(),old_content:Some("original".into())};std::fs::write(work.join("journal.json"),serde_json::to_vec(&journal).unwrap()).unwrap();recover(&root,&c).unwrap();assert_eq!(std::fs::read_to_string(root.join("old/SKILL.md")).unwrap(),"original");std::fs::rename(root.join("old"),root.join("new")).unwrap();std::fs::create_dir(&work).unwrap();std::fs::write(work.join("journal.json"),serde_json::to_vec(&journal).unwrap()).unwrap();c.execute("INSERT INTO setting_default(scope,key,value,updatedAt) VALUES('global',?1,'1',0)",[marker("interrupted")]).unwrap();recover(&root,&c).unwrap();assert!(root.join("new/SKILL.md").exists());assert!(!root.join("old").exists());std::fs::remove_dir_all(root).unwrap();}
}
